/** Counts are recomputed from the live catalog so they can never drift. */
export const brands: BrandEntry[] = RAW_BRANDS.map((brand) => ({
  ...brand,
  count: products.filter((p) => p.brand === brand.name).length,
})).filter((brand) => brand.count > 0);

export const brandBySlug: Map<string, BrandEntry> = new Map(
  brands.map((brand) => [brand.slug, brand]),
);
